  if (view === 'login') {
    return (
      <div className="min-h-screen bg-[#020617] flex items-center justify-center p-6 text-white">
        <div className="w-full max-w-md space-y-8">
           <button onClick={() => setView('landing')} className="text-slate-500 hover:text-white flex items-center gap-2 text-[10px] font-black uppercase tracking-widest"><ArrowRight size={16} className="rotate-180" /> Back</button>
           <div className="bg-[#0f172a] p-10 rounded-[3.5rem] border border-slate-800 shadow-2xl space-y-8">
              <h2 className="text-2xl font-black uppercase text-center">{role} Login</h2>
              <form onSubmit={handleLoginSubmit} className="space-y-4">
                 <input required className="w-full p-4 bg-slate-900 border border-slate-800 rounded-2xl outline-none focus:border-indigo-500 font-bold text-white" placeholder="Email Address" />
                 <input required type="password" defaultValue="demo123" className="w-full p-4 bg-slate-900 border border-slate-800 rounded-2xl outline-none focus:border-indigo-500 font-bold text-white" placeholder="Password" />
                 <button type="submit" disabled={isLoading} className="w-full py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest text-xs">
                    {isLoading ? 'Authenticating...' : 'Enter Dashboard'}
                 </button>
              </form>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900">
      <nav className="bg-white/80 backdrop-blur-xl border-b sticky top-0 z-[80] px-8 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3 font-black text-2xl tracking-tighter italic">
          <BrainCircuit className="text-indigo-600" size={22}/> SUCCESS<span className="text-indigo-600">PREDICT</span>
        </div>
        <button onClick={logout} className="bg-rose-50 text-rose-500 p-3 rounded-2xl hover:bg-rose-100 transition-all"><LogOut size={20} /></button>
      </nav>
      <main className="max-w-7xl mx-auto p-6 sm:p-12">
        {role === 'student' && <StudentPortal />}
        {role === 'teacher' && <TeacherPortal />}
        {role === 'admin' && <AdminPortal />}
      </main>
    </div>
  );
}
